import unittest
from service import authorize

class Tests(unittest.TestCase):
    def test_allowed(self): self.assertTrue(authorize('Bearer abc', {'abc': ['read']}, 'read'))
    def test_missing(self): self.assertFalse(authorize('', {}, 'read'))
    def test_wrong_scheme(self): self.assertFalse(authorize('Basic abc', {'abc': ['read']}, 'read'))
    def test_denied(self): self.assertFalse(authorize('Bearer abc', {'abc': ['read']}, 'write'))
